// Reconcile Uptime Kuma monitors with a JSON file generated by fmf.services.uptime-kuma.
//
// Talks to Kuma's own Socket.IO API (the one its web UI uses) with the socket.io-client that ships
// inside the Uptime Kuma package, so the protocol always matches the server.
//
// Managed monitors carry one tag (KUMA_TAG, default "nix") whose value is the monitor's key from
// the JSON file. That tag is the only thing used to decide ownership:
//   * key in the file, no tagged monitor  -> add it and tag it
//   * key in the file, tagged monitor     -> edit it if a managed field differs
//   * tagged monitor, key not in the file -> delete it
// Monitors without the tag (added in the UI) are never touched.
//
// Environment:
//   KUMA_URL             e.g. http://127.0.0.1:4000
//   KUMA_MONITORS_FILE   JSON object: key -> Kuma monitor fields
//   KUMA_USERNAME_FILE   file holding the admin username
//   KUMA_PASSWORD_FILE   file holding the admin password
//   KUMA_TAG             tag name marking managed monitors (default "nix")
//   KUMA_WAIT_SECONDS    how long to wait for Kuma to accept connections (default 300)
//   KUMA_DRY_RUN=1       log what would change, change nothing
"use strict";

const fs = require("fs");
const { io } = require("socket.io-client");

const env = (name, fallback) => {
  const v = process.env[name] ?? fallback;
  if (v === undefined) {
    throw new Error(`${name} is not set`);
  }
  return v;
};
const readSecret = (file) => fs.readFileSync(file, "utf8").trim();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log(...a);

// Fields Kuma's "add" handler expects to be present (it JSON-encodes them unconditionally).
const ADD_DEFAULTS = {
  notificationIDList: {},
  accepted_statuscodes: ["200-299"],
  kafkaProducerBrokers: [],
  kafkaProducerSaslOptions: { mechanism: "None" },
  rabbitmqNodes: [],
  conditions: [],
  method: "GET",
  maxredirects: 10,
  timeout: 48,
  resendInterval: 0,
  ignoreTls: false,
  upsideDown: false,
  expiryNotification: false,
  httpBodyEncoding: "json",
  parent: null,
  active: true,
};

function call(socket, event, ...args) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error(`${event}: no answer within 60s`)), 60000);
    socket.emit(event, ...args, (res) => {
      clearTimeout(t);
      resolve(res);
    });
  });
}

function must(res, what) {
  if (!res || res.ok === false) {
    throw new Error(`${what} failed: ${(res && res.msg) || "no response"}`);
  }
  return res;
}

// Kuma accepts the socket before it is ready (on a fresh database it is still migrating) and only
// registers its handlers after it has sent "info" to the new connection; anything emitted earlier is
// dropped. So a connection counts as ready only once "info" has arrived.
async function connect(url, waitSeconds) {
  const deadline = Date.now() + waitSeconds * 1000;
  for (;;) {
    try {
      return await new Promise((resolve, reject) => {
        const s = io(url, { transports: ["websocket"], reconnection: false, timeout: 10000 });
        const fail = (e) => {
          clearTimeout(t);
          s.close();
          reject(e);
        };
        const t = setTimeout(() => fail(new Error("connected, but Kuma sent no info within 15s")), 15000);
        s.once("info", () => {
          clearTimeout(t);
          // The handlers are registered right after "info" is sent; give the event loop a moment.
          setTimeout(() => resolve(s), 500);
        });
        s.once("connect_error", fail);
      });
    } catch (e) {
      if (Date.now() > deadline) {
        throw new Error(`cannot reach Uptime Kuma at ${url}: ${e.message}`);
      }
      await sleep(3000);
    }
  }
}

const same = (a, b) => JSON.stringify(a ?? null) === JSON.stringify(b ?? null);

async function main() {
  const url = env("KUMA_URL");
  const desired = JSON.parse(fs.readFileSync(env("KUMA_MONITORS_FILE"), "utf8"));
  const tagName = env("KUMA_TAG", "nix");
  const dryRun = env("KUMA_DRY_RUN", "0") === "1";
  const username = readSecret(env("KUMA_USERNAME_FILE"));
  const password = readSecret(env("KUMA_PASSWORD_FILE"));

  const socket = await connect(url, Number(env("KUMA_WAIT_SECONDS", "300")));
  let monitorList = null;
  socket.on("monitorList", (l) => {
    monitorList = l;
  });

  try {
    // A fresh instance has no admin yet: create it from the same credentials.
    if (await call(socket, "needSetup")) {
      if (dryRun) {
        log("dry run: Uptime Kuma needs setup; would create the admin user and stop here");
        return;
      }
      must(await call(socket, "setup", username, password), "initial setup");
      log(`created admin user '${username}'`);
    }

    const login = await call(socket, "login", { username, password, token: "" });
    if (login && login.tokenRequired) {
      throw new Error("the admin account has 2FA enabled; provisioning cannot log in with it");
    }
    must(login, "login");

    // getMonitorList emits "monitorList" before it answers.
    must(await call(socket, "getMonitorList"), "getMonitorList");
    if (monitorList === null) {
      throw new Error("Uptime Kuma did not send its monitor list");
    }

    const tags = must(await call(socket, "getTags"), "getTags").tags;
    let tag = tags.find((t) => t.name === tagName);
    if (!tag) {
      if (dryRun) {
        tag = { id: -1 };
        log(`dry run: would create tag '${tagName}'`);
      } else {
        tag = must(await call(socket, "addTag", { name: tagName, color: "#2563EB" }), "addTag").tag;
        log(`created tag '${tagName}'`);
      }
    }

    // key -> existing managed monitor. A second monitor with the same key is a leftover: delete it.
    const managed = new Map();
    const duplicates = [];
    for (const m of Object.values(monitorList)) {
      const t = (m.tags || []).find((x) => x.tag_id === tag.id);
      if (!t) {
        continue;
      }
      if (managed.has(t.value)) {
        duplicates.push(m);
      } else {
        managed.set(t.value, m);
      }
    }

    const counts = { added: 0, updated: 0, unchanged: 0, deleted: 0 };

    for (const [key, fields] of Object.entries(desired)) {
      const existing = managed.get(key);
      if (!existing) {
        log(`add    ${key} (${fields.url || fields.hostname || fields.type})`);
        counts.added++;
        if (!dryRun) {
          const res = must(await call(socket, "add", { ...ADD_DEFAULTS, ...fields }), `add ${key}`);
          must(await call(socket, "addMonitorTag", tag.id, res.monitorID, key), `tag ${key}`);
        }
        continue;
      }
      const changed = Object.keys(fields).filter((k) => !same(existing[k], fields[k]));
      if (changed.length === 0) {
        counts.unchanged++;
        continue;
      }
      log(`update ${key}: ${changed.join(", ")}`);
      counts.updated++;
      if (!dryRun) {
        // editMonitor overwrites every column, so start from the monitor as Kuma has it.
        must(await call(socket, "editMonitor", { ...existing, ...fields, id: existing.id }), `update ${key}`);
      }
    }

    const stale = [...managed.entries()].filter(([key]) => !(key in desired)).map(([, m]) => m);
    for (const m of [...stale, ...duplicates]) {
      log(`delete ${m.name} (id ${m.id})`);
      counts.deleted++;
      if (!dryRun) {
        must(await call(socket, "deleteMonitor", m.id, false), `delete ${m.name}`);
      }
    }

    log(
      `${dryRun ? "dry run: " : ""}${counts.added} added, ${counts.updated} updated, ` +
        `${counts.unchanged} unchanged, ${counts.deleted} deleted`,
    );
  } finally {
    socket.close();
  }
}

main().catch((e) => {
  console.error(`uptime-kuma-provision: ${e.message}`);
  process.exit(1);
});
